import{d as g,C as t,o as c,c as u,j as a,a as s,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第八十一章","description":"从信美、善辩、知博三组对照读不积与助人，以利而不害、为而不争收束。","frontmatter":{"title":"道德经第八十一章","description":"从信美、善辩、知博三组对照读不积与助人，以利而不害、为而不争收束。","category":"guide","aliases":["道德经第八十一章","老子第八十一章","dao de jing chapter 81"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-81.md","filePath":"daoism/dao-de-jing/chapter-81.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-81.md"},w=g({...m,setup(x){const r=[{id:"trustworthy-and-ornate-words",label:"信言不美，美言不信",showLabel:!0,sentences:[[{text:"信",glossary:"xin-trust"},"言不",{text:"美",glossary:"mei-praise"},"，",{text:"美",glossary:"mei-praise"},"言不",{text:"信",glossary:"xin-trust"},"。"]],note:["【白话】真实可信的话不以华美为长，华美动听的话却未必可信。原文用鲜明对举，把判断的重心从文饰转回真实。","【王弼注择要】信言不美下注「实在质也」，美言不信下注「本在朴也」。","【读法】白话的未必用于说明勿以华美判断可信，不是替换原文不信的强烈语气。王注重质与朴；表达清楚、形式好看，都不能单独证明或否定内容真实。"]},{id:"goodness-and-contention",label:"善者不辩，辩者不善",showLabel:!0,sentences:[[{text:"善",glossary:"shan-good"},"者不",{text:"辩",glossary:"bian-argue"},"，",{text:"辩",glossary:"bian-argue"},"者不",{text:"善",glossary:"shan-good"},"。"]],note:["【白话】善的人不靠争辩求胜，专以争辩取胜的人却不善。第二组把判断从说得赢转向行得善。","【读法】所据此句后未另见独立王注，本页依上下文解释。辩取争辩之义；不把善者不辩用来封住合理质疑、拒绝说明或取消必要的事实辨析。"]},{id:"knowledge-and-extensive-learning",label:"知者不博，博者不知",showLabel:!0,sentences:[[{text:"知",glossary:"zhi-cunning"},"者不",{text:"博",glossary:"bo-extensive"},"，",{text:"博",glossary:"bo-extensive"},"者不",{text:"知",glossary:"zhi-cunning"},"。"]],note:["【白话】真正有所知的人不以广博多闻为所重，专求广博多闻的人却未必真有所知。第三组追问所知是否触及根本。","【王弼注择要】知者不博下注「极在一也」。","【读法】依王注，一是理解所归的根本；不博与此相对，不是赞扬少学。知在本页取认识、了解义，读 zhī，不套用第三章智巧、读 zhì 的义项；广泛学习能否形成理解，仍须具体检查。"]},{id:"not-hoarding-for-oneself",label:"圣人不积",showLabel:!0,sentences:[["圣人不",{text:"积",glossary:"ji-accumulate"},"，"]],note:["【白话】圣人不把所有一味积聚为自己的占有。接下来的两句将不积落实到为别人做事和给予别人。","【王弼注择要】「无私自有，唯善是与，任物而已。」","【读法】注语重在不私自占有、任物，不能只译成完全没有任何积蓄。合理生活储备、知识学习与一味私积，应分别讨论。"]},{id:"acting-for-others",label:"既以为人己愈有",showLabel:!0,sentences:[[{text:"既",glossary:"ji-exhaust"},"以",{text:"为人",glossary:"weiren-serve"},"己",{text:"愈",glossary:"yu-increasingly"},"有，"]],note:["【白话】尽力用来为别人做事，自己反而越发有所充实。这里的为人，指替他人尽力；己愈有承接这种行动。","【王弼注择要】「物所尊也。」","【读法】既本页取尽义，为人读 wèi rén；王注从为物所尊说明有的增益。不能把己愈有改作每次帮助别人都必定得到更多财物。"]},{id:"giving-to-others",label:"既以与人己愈多",showLabel:!0,sentences:[[{text:"既",glossary:"ji-exhaust"},"以",{text:"与",glossary:"yu-associate"},"人己",{text:"愈",glossary:"yu-increasingly"},"多。"]],note:["【白话】尽力拿来给予别人，自己反而越发丰厚。与人明确说给予，与前句替别人做事相接。","【王弼注择要】「物所归也。」","【读法】与读 yǔ，取给予义；王注以物所归说明多。古文的价值表达不等于可计算的投资回报，也不能据此要求个人超出能力地持续付出。"]},{id:"benefiting-without-harming",label:"天之道，利而不害",showLabel:!0,sentences:[["天之道，",{text:"利",glossary:"li-benefit"},"而不",{text:"害",glossary:"hai-harm"},"；"]],note:["【白话】天的运行之道，是使万物得益而不加害。末段先以天道说明成全与伤害的方向。","【王弼注择要】「动常生成之也。」","【读法】注中生成连万物的生长成就来读。这里保留古代天道的理想表达，不把它当作自然界永远没有灾害的经验事实。"]},{id:"acting-without-competing",label:"圣人之道，为而不争",showLabel:!0,sentences:[["圣人之道，",{text:"为",glossary:"wei-impose"},"而",{text:"不争",glossary:"buzheng"},"。"]],note:["【白话】圣人的行事之道，是有所作为，却不以争夺求胜。为与不争并列，说明不争并没有取消做事。","【王弼注择要】「顺天之利，不相伤也。」","【读法】为读 wéi。与第八章水善利万物而不争、第二章为而不恃相参，可以看出利物、行动与不自争的联系；这种参读不等于断定本章概括了全书唯一的思想中心。"]}],i=[{id:"xin-trust",term:"信",sense:1},{id:"mei-praise",term:"美",sense:2},{id:"shan-good",term:"善",sense:1},{id:"bian-argue",term:"辩",sense:1},{id:"zhi-cunning",term:"知",sense:2,pinyin:"zhī"},{id:"bo-extensive",term:"博",sense:1},{id:"ji-accumulate",term:"积",sense:1},{id:"ji-exhaust",term:"既",sense:1},{id:"weiren-serve",term:"为人",sense:1},{id:"yu-associate",term:"与",sense:2},{id:"yu-increasingly",term:"愈",sense:1},{id:"li-benefit",term:"利",sense:2},{id:"hai-harm",term:"害",sense:1},{id:"wei-impose",term:"为",sense:2},{id:"buzheng",term:"不争",sense:1}];return(p,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第八十一章",tabindex:"-1"},[s("道德经第八十一章 "),a("a",{class:"header-anchor",href:"#道德经第八十一章","aria-label":'Permalink to "道德经第八十一章"'},"​")],-1)),n(o,{title:"不靠文饰与占有，怎样仍能有所作为",summary:"末章先将真实与文饰、善行与争辩、真知与广博并置，再转到圣人不积、为人和与人。王注以质、朴、一说明前三组，以物所尊、物所归说明助人给予的增益。最后落在天道利而不害、圣人为而不争：行动并未消失，所反省的是靠文饰、争胜与占有建立自身。",points:[{label:"先读",text:"先将信美、善辩、知博三组对照读清，再看王注各自的重心。"},{label:"再辨",text:"不积承接为人、与人，己愈有、己愈多不是付出必得物质回报的保证。"},{label:"后看",text:"从利而不害读到为而不争，保留行动，也辨清行动的方式。"}],hint:"辩读 biàn，博读 bó，积读 jī，愈读 yù。知者的知本页读 zhī；为人读 wèi rén，末句为读 wéi；与人读 yǔ rén。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:r,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"信言不美，美言不信。",tone:"把判断落在真实",guide:"先辨内容是否可信，再看文辞如何表达。"},{text:"圣人不积，既以为人己愈有，既以与人己愈多。",tone:"从私积转向助人与给予",guide:"王注以物所尊、物所归解释增益，不当作回报承诺。"},{text:"天之道，利而不害；圣人之道，为而不争。",tone:"保留行动，反省争胜",guide:"利、为都是动作，不害、不争说明其方向与方式。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:i}),e[4]||(e[4]=b("",15))])}}});export{f as __pageData,w as default};
